from pathlib import Path
import unittest

scope = {}
exec(compile(Path('cache.py').read_text(encoding='utf-8'), 'cache.py', 'exec'), scope)
Cache = scope['Cache']

class CacheCharacterization(unittest.TestCase):
    def test_fresh_miss(self):
        with self.assertRaises(KeyError): Cache().get('missing', 100)
    def test_hit_before_expiry(self):
        c = Cache(); c.set('a', 'v', 100, 10)
        self.assertEqual(c.get('a', 109), 'v')
    def test_exact_expiry(self):
        c = Cache(); c.set('a', 'v', 100, 10)
        self.assertIsNone(c.get('a', 110))
    def test_after_expiry(self):
        c = Cache(); c.set('a', 'v', 100, 10)
        self.assertIsNone(c.get('a', 111))
    def test_overwrite_value_and_deadline(self):
        c = Cache(); c.set('a', 'old', 100, 10); c.set('a', 'new', 105, 20)
        self.assertEqual(c.values['a'], ('new', 125))
        self.assertEqual(c.get('a', 110), 'new')
        self.assertIsNone(c.get('a', 125))
    def test_keys_independent(self):
        c = Cache(); c.set('a', 1, 100, 10); c.set('b', 2, 100, 20)
        self.assertIsNone(c.get('a', 110)); self.assertEqual(c.get('b', 110), 2)
    def test_instances_independent(self):
        c = Cache(); c.set('a', 1, 100, 10)
        with self.assertRaises(KeyError): Cache().get('a', 100)
    def test_zero_ttl(self):
        c = Cache(); c.set('a', 'v', 100, 0)
        self.assertIsNone(c.get('a', 100))
    def test_negative_ttl(self):
        c = Cache(); c.set('a', 'v', 100, -1)
        self.assertIsNone(c.get('a', 100))
    def test_falsy_values(self):
        for value in (0, False, '', [], None):
            with self.subTest(value=value):
                c = Cache(); c.set('a', value, 100, 10)
                self.assertIs(c.get('a', 100), value)
    def test_expired_record_retained(self):
        c = Cache(); c.set('a', 'v', 100, 10); c.get('a', 110)
        self.assertEqual(c.values['a'], ('v', 110))
    def test_backwards_time_reveals_expired_value(self):
        c = Cache(); c.set('a', 'v', 100, 10)
        self.assertIsNone(c.get('a', 110)); self.assertEqual(c.get('a', 109), 'v')
    def test_get_does_not_refresh_ttl(self):
        c = Cache(); c.set('a', 'v', 100, 10); c.get('a', 109)
        self.assertIsNone(c.get('a', 110))
    def test_fractional_time(self):
        c = Cache(); c.set('a', 'v', 1.0, 0.5)
        self.assertEqual(c.get('a', 1.25), 'v'); self.assertIsNone(c.get('a', 1.5))
    def test_mutable_value_is_shared(self):
        c = Cache(); value = []; c.set('a', value, 100, 10); value.append(1)
        self.assertIs(c.get('a', 100), value); self.assertEqual(c.get('a', 100), [1])
    def test_unhashable_key(self):
        c = Cache()
        with self.assertRaises(TypeError): c.set([], 'v', 100, 10)
        with self.assertRaises(TypeError): c.get([], 100)

result = unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(CacheCharacterization))
raise SystemExit(not result.wasSuccessful())
